  .nav.open { display: flex; flex-direction: column; position: absolute; top: 100%; left: 0; right: 0; background: var(--white); padding: 24px; box-shadow: var(--shadow-lg); gap: 16px; z-index: 99; }
  .section { padding: 48px 0; }
  .section-title { font-size: 1.5rem; }
  .hero-carousel .slide-title { font-size: 1.8rem; }
  .hero-carousel .slide { padding: 48px 0; min-height: auto; }
  .hero-carousel { min-height: auto; }
  .course-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 16px; }
  .course-carousel .carousel-track .course-card { min-width: calc(50% - 10px); }
  .masonry-grid { columns: 2; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-section h4 { display: none; }
  .footer-section .toggle-btn { display: flex; }
  .footer-section .footer-links { display: none; }
  .footer-section .footer-links.open { display: block; }
  .plus-hero h1 { font-size: 2.2rem; }
  .pricing-cards { grid-template-columns: 1fr; }
